EntryPointV2.InputArguments:
{
  "type": "object",
  "required": [
    "correlationId",
    "invoiceRecordId",
    "contractProfileId",
    "invoiceDate",
    "canonicalCharges",
    "reconciliationSummary",
    "precedencePolicy"
  ],
  "properties": {
    "correlationId": {
      "type": "string",
      "description": "Cross-component trace identifier"
    },
    "invoiceRecordId": {
      "type": "string",
      "description": "HLS_InvoiceAssurance_Main system identifier"
    },
    "contractProfileId": {
      "type": "string",
      "description": "Selected governed contract profile identifier"
    },
    "invoiceDate": {
      "type": "string",
      "description": "Invoice effective-date anchor in YYYY-MM-DD format"
    },
    "canonicalCharges": {
      "type": "array",
      "description": "Normalized invoice charges with document and evidence references. When changedFindingIds is non-empty, only charges whose chargeId or category shares the targeted finding-topic token are in scope; all other entries are decoys that must not be retrieved, analyzed, mentioned, or emitted.",
      "items": {
        "type": "object",
        "required": [
          "chargeId",
          "category",
          "submittedAmount"
        ],
        "properties": {
          "chargeId": {
            "type": "string"
          },
          "category": {
            "type": "string"
          },
          "description": {
            "type": "string"
          },
          "serviceDate": {
            "type": "string",
            "nullable": true
          },
          "quantity": {
            "type": "number"
          },
          "unit": {
            "type": "string"
          },
          "unitRate": {
            "type": "number"
          },
          "submittedAmount": {
            "type": "number"
          },
          "evidenceTypes": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "sourceDocumentId": {
            "type": "string"
          }
        }
      }
    },
    "reconciliationSummary": {
      "type": "object",
      "description": "Completed project, invoice, register, and supporting-document comparison facts"
    },
    "precedencePolicy": {
      "type": "object",
      "description": "Generic metadata and policy for effective dates and topic-specific document precedence"
    },
    "humanOverride": {
      "type": "string",
      "description": "Optional audited interpretation instruction limited to indexed contract documents",
      "nullable": true
    },
    "changedFindingIds": {
      "type": "array",
      "description": "Exclusive targeted re-evaluation scope when non-empty. Derive topic tokens from each finding ID (for example finding-ppe-evidence targets ppe), inspect only charges sharing those topic tokens, and ignore all unrelated charges and reconciliation facts as decoys.",
      "nullable": true,
      "items": {
        "type": "string"
      }
    }
  }
}

EntryPointV2.OutputArguments:
{
  "type": "object",
  "required": [
    "governingDocumentStack",
    "normalizedRules",
    "proposedFindings",
    "ambiguities",
    "analysisSummary",
    "schemaVersion"
  ],
  "properties": {
    "governingDocumentStack": {
      "type": "array",
      "description": "Effective indexed documents with topic scope and applicability reasons",
      "items": {
        "type": "object",
        "required": [
          "sourceDocumentId",
          "documentTitle",
          "topicScope",
          "reason"
        ],
        "properties": {
          "sourceDocumentId": {
            "type": "string"
          },
          "documentTitle": {
            "type": "string"
          },
          "effectiveDate": {
            "type": "string",
            "nullable": true
          },
          "topicScope": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "reason": {
            "type": "string"
          }
        }
      }
    },
    "normalizedRules": {
      "type": "array",
      "description": "Grounded supported rules for deterministic evaluation",
      "items": {
        "type": "object",
        "required": [
          "ruleId",
          "ruleType",
          "scope",
          "operands",
          "effectivePeriod",
          "sourceDocumentId",
          "sourceClause",
          "confidence"
        ],
        "properties": {
          "ruleId": {
            "type": "string"
          },
          "ruleType": {
            "type": "string"
          },
          "scope": {
            "type": "object"
          },
          "operands": {
            "type": "object"
          },
          "effectivePeriod": {
            "type": "object"
          },
          "sourceDocumentId": {
            "type": "string"
          },
          "sourceClause": {
            "type": "string"
          },
          "confidence": {
            "type": "number"
          }
        }
      }
    },
    "proposedFindings": {
      "type": "array",
      "description": "Exception-only charge-to-rule associations. Include only exceeded limits or caps, excluded categories, missing required evidence, or non-zero reconciliation exceptions. Never include supported, compliant, satisfied, tied, or unchanged items; use an empty array when no exception exists.",
      "items": {
        "type": "object",
        "required": [
          "findingId",
          "chargeId",
          "ruleId",
          "evidenceState",
          "explanation",
          "citations"
        ],
        "properties": {
          "findingId": {
            "type": "string"
          },
          "chargeId": {
            "type": "string"
          },
          "ruleId": {
            "type": "string"
          },
          "evidenceState": {
            "type": "string",
            "description": "Exception state only. Never infer missingEvidence from an empty evidenceTypes array unless a retrieved category-specific EvidenceRequirement expressly requires an input evidence type and its threshold applies.",
            "enum": [
              "exceededLimit",
              "exceededCap",
              "excludedCategory",
              "missingEvidence",
              "reconciliationException"
            ]
          },
          "explanation": {
            "type": "string"
          },
          "citations": {
            "type": "array",
            "items": {
              "type": "object",
              "required": [
                "sourceDocumentId",
                "sourceClause"
              ],
              "properties": {
                "sourceDocumentId": {
                  "type": "string"
                },
                "sourceClause": {
                  "type": "string"
                }
              }
            }
          }
        }
      }
    },
    "ambiguities": {
      "type": "array",
      "description": "Only conflicting applicability, absent contract support, or unsupported rule concepts that block a relevant decision. Do not use for compliant values, resolved evidence, tied reconciliation, or generic charges.",
      "items": {
        "type": "object",
        "required": [
          "ambiguityId",
          "topic",
          "explanation",
          "affectedChargeIds",
          "citations"
        ],
        "properties": {
          "ambiguityId": {
            "type": "string"
          },
          "topic": {
            "type": "string"
          },
          "explanation": {
            "type": "string"
          },
          "affectedChargeIds": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "citations": {
            "type": "array",
            "items": {
              "type": "object",
              "required": [
                "sourceDocumentId",
                "sourceClause"
              ],
              "properties": {
                "sourceDocumentId": {
                  "type": "string"
                },
                "sourceClause": {
                  "type": "string"
                }
              }
            }
          }
        }
      }
    },
    "analysisSummary": {
      "type": "string",
      "description": "Concise non-legal explanation of governing rules, proposals, and open ambiguity"
    },
    "schemaVersion": {
      "type": "string",
      "description": "Agent output contract version"
    }
  }
}

